import pytest
from isort.settings import DEFAULT_CONFIG, Config
from isort.exceptions import MissingSection
from isort.parse import file_contents

def test_file_contents_basic():
    content = "import os\nimport sys\n"
    res = file_contents(content)
    assert res.import_index >= 0
    assert any("os" in res.imports[sec]["straight"] for sec in res.imports)

def test_file_contents_line_ending_and_newlines():
    content_cr = "import os\r"
    res1 = file_contents(content_cr)
    assert res1.line_separator == "\r"

    content_no_nl = "import os"
    res2 = file_contents(content_no_nl)
    assert res2.in_lines[-1] == "import os"

def test_file_contents_old_finders():
    config = Config(old_finders=True)
    content = "import os\n"
    res = file_contents(content, config=config)
    assert res is not None

def test_file_contents_section_comments():
    content = "# -- custom section --\nimport os\n# -- end --\n"
    # DEFAULT_CONFIG has section_comments
    res = file_contents(content, config=DEFAULT_CONFIG)
    assert res.import_index >= 0

def test_file_contents_isort_imports_tags():
    content = "# isort:imports-FIRSTPARTY\nimport mylib\n# isort: imports-LOCALFOLDER\nimport localmod\n"
    res = file_contents(content)
    assert "FIRSTPARTY" in res.place_imports
    assert "LOCALFOLDER" in res.place_imports

def test_file_contents_skipping_line():
    content = "# isort:skip_file\nimport os\n"
    res = file_contents(content)
    assert res is not None

def test_file_contents_float_to_top():
    content = (
        "x = 1\n"
        "# isort:skip (\n"
        "import os\n"
        "import sys\n"
    )
    config = Config(float_to_top=True)
    res = file_contents(content, config=config)
    assert res is not None

def test_file_contents_float_to_top_extended_skip():
    content = (
        "x = 1\n"
        "# isort: skip (\n"
        "# multiline\n"
        ")\n"
        "import os\n"
    )
    config = Config(float_to_top=True)
    res = file_contents(content, config=config)
    assert res is not None

def test_file_contents_statements_semicolon_and_comments():
    content = "import os; import sys # end comment\n"
    res = file_contents(content)
    assert any("os" in res.imports[sec]["straight"] for sec in res.imports)
    assert any("sys" in res.imports[sec]["straight"] for sec in res.imports)

def test_file_contents_from_import_syntax():
    content = "from os import path, getcwd as _getcwd\n"
    res = file_contents(content)
    assert any("os" in res.imports[sec]["from"] for sec in res.imports)

def test_file_contents_parentheses_multiline_import():
    content = (
        "from os import (\n"
        "    path,  # path comment\n"
        "    getcwd,\n"
        ")\n"
    )
    res = file_contents(content)
    assert any("os" in res.imports[sec]["from"] for sec in res.imports)

def test_file_contents_escaped_line_import():
    content = (
        "from os import \\\n"
        "    path, \\\n"
        "    getcwd\n"
    )
    res = file_contents(content)
    assert any("os" in res.imports[sec]["from"] for sec in res.imports)

def test_file_contents_cimports():
    content = "from cysignals cimport sig_on\n"
    res = file_contents(content)
    assert any("cysignals" in res.imports[sec]["from"] for sec in res.imports)

def test_file_contents_no_import_keyword_in_from():
    content = "from os corrupt\n"
    res = file_contents(content)
    assert len(res.lines_without_imports) > 0

def test_file_contents_as_imports_and_redundant_aliases():
    config = Config(remove_redundant_aliases=True, combine_as_imports=True)
    content = "import os as os\nfrom sys import version as version\n"
    res = file_contents(content, config=config)
    assert res is not None

def test_file_contents_as_map_and_nested_comments():
    content = "from os import path as p  # p comment\nimport sys as s\n"
    res = file_contents(content)
    assert res.as_map["from"] is not None

def test_file_contents_verbose_and_only_modified():
    config = Config(verbose=True, only_modified=False)
    content = "from os import path\n"
    res = file_contents(content, config=config)
    assert res is not None

def test_file_contents_verbose_only_modified():
    config = Config(verbose=True, only_modified=True)
    content = "from os import path\n"
    res = file_contents(content, config=config)
    assert res is not None

def test_file_contents_missing_section_raises():
    config = Config(sections=["STDLIB"])
    content = "import nonexistent_module_xyz_12345\n"
    with pytest.raises(MissingSection):
        file_contents(content, config=config)

def test_file_contents_force_single_line_comments():
    config = Config(force_single_line=True)
    content = "from os import (  # comment\n    path\n)\n"
    res = file_contents(content, config=config)
    assert res is not None

def test_file_contents_above_comments_processing():
    content = (
        "# Above comment\n"
        "import os\n"
    )
    res = file_contents(content)
    assert len(res.categorized_comments["above"]["straight"]) >= 0

def test_file_contents_above_comments_from():
    content = (
        "# Above comment\n"
        "from os import path\n"
    )
    res = file_contents(content)
    assert len(res.categorized_comments["above"]["from"]) >= 0

def test_file_contents_treat_all_comments_as_code():
    config = Config(treat_all_comments_as_code=True)
    content = (
        "# Above comment\n"
        "from os import path\n"
    )
    res = file_contents(content, config=config)
    assert res is not None

def test_file_contents_treat_comments_as_code_set():
    config = Config(treat_comments_as_code=frozenset(["# Above comment"]))
    content = (
        "# Above comment\n"
        "from os import path\n"
    )
    res = file_contents(content, config=config)
    assert res is not None

def test_file_contents_trailing_comma():
    content = "from os import (\n    path,\n)\n"
    res = file_contents(content)
    assert "os" in res.trailing_commas

def test_file_contents_straight_import_duplicates():
    content = "import os\nimport os\n"
    res = file_contents(content)
    assert any("os" in res.imports[sec]["straight"] for sec in res.imports)
